original_release_check_sop:
{
  "steps": [
    {
      "step_id": "S1",
      "source_lines": [6, 7, 8],
      "source_quote": "Run the unit tests before tagging a release.\n$ python -m unittest discover -s tests\nThe test run must exit with status zero.",
      "tote": {
        "initial_test": "Check if unit tests are passing",
        "operate": "python -m unittest discover -s tests",
        "exit": "Exit status is zero",
        "max_iterations": 3
      },
