        {
          "type": "exit_code_equals",
          "params": {
            "value": 0
          },
          "basis": "source_stated"
        }
      ]
    },
    {
      "step_id": "S2",
      "source_lines": [9],
      "source_quote": "The p95 latency must not be higher than 250 milliseconds.",
      "tote": {
        "initial_test": "Measure p95 latency",
        "operate": "Run latency benchmark",
        "exit": "p95 latency <= 250ms",
        "max_iterations": 1
