        }
      ]
    },
    {
      "step_id": "S3",
      "source_lines": [10],
      "source_quote": "Confirm that the changelog describes every user-visible change.",
      "tote": {
        "initial_test": "Review changelog content",
        "operate": "Compare changelog against user-visible changes",
        "exit": "Changelog is complete",
        "max_iterations": 1
      },
      "exit_checks": [
        {
          "type": "human_review",
          "params": {},
          "basis": "human_judgement"
        }
      ]
    },
    {
      "step_id": "S4",
      "source_lines": [11, 12],
